-- Massa de fábrica do Elastic Journey.
-- Gerada a partir do estado funcional validado em 2026-09-08, atualizada em 2026-09-13 com o
-- produto Laboratorio e a jornada "Vivo Fibra + Total — Contratação".
-- Não contém auditoria, publicação derivada, deployment de runtime nem segredo real.
-- As jornadas e versões são semeadas como UNPUBLISHED e republicadas pelas APIs oficiais.

BEGIN;

TRUNCATE TABLE
  audit_event,
  journey_publication,
  journey_version,
  flow,
  journey_channel_type,
  journey,
  product_channel_type,
  credential_reference,
  messaging_cluster,
  ai_provider_credential,
  component_definition,
  product
CASCADE;


COMMIT;
